const fs=require('fs'),cp=require('child_process'),a=require('assert/strict');for(const name of ['restore.cjs','hosted-cli-ui.cjs','collect-native-groups.cjs']){const p=cp.spawnSync(process.execPath,[__dirname+'/'+name],{stdio:'inherit',env:process.env});fs.appendFileSync(__dirname+'/stages.jsonl',JSON.stringify({at:new Date().toISOString(),name,exit:p.status})+'\n');a.equal(p.status,0,name)}
